UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8')
    if t.startswith('﻿'):
        t = t[1:]
    return t


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip()]


def files_in(d):
    out = []
    if os.path.isdir(d):
        for root, _, fs in os.walk(d):
            for f in fs:
                out.append(os.path.join(root, f))
    return sorted(out)


def to_epoch(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_epoch(naive, tz, fold=0):
    return to_epoch(naive.replace(tzinfo=tz, fold=fold))


def std_offset(tz, naive):
    d = naive.replace(tzinfo=tz)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_12_24(s):
    s = s.strip()
    ampm = None
    up = s.upper()
    if up.endswith('AM') or up.endswith('PM'):
        ampm = up[-2:]
        s = s[:-2].strip()
    h, m, sec = (s.split(':') + ['0'])[:3]
    h, m, sec = int(h), int(m), int(sec)
    if ampm == 'AM':
        h = h % 12
    elif ampm == 'PM':
        h = h % 12 + 12
    return dtime(h, m, sec)


# ---- readers: each yields (id, emp, dir, epoch) ----

def read_abbr(path, tz):
    header = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        mo, d, y = r['Date'].split('/')
        t = parse_12_24(r['Time'])
        naive = datetime(int(y), int(mo), int(d), t.hour, t.minute, t.second)
        z = r.get('Zone', '').upper()
        fold = 0 if z.endswith('DT') else 1
        yield (r['Record'], r['Badge'], r['Punch'].upper(), local_to_epoch(naive, tz, fold))


def read_epoch(path, tz):
    schema = 1
    for line in lines_of(path):
        o = json.loads(line)
        if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            yield (str(o['punch_id']), o['employee'], str(o['direction']).upper(),
                   int(o['epoch_ms']) // 1000)
        else:
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
            yield (str(o['id']), o['emp'], str(o['dir']).upper(), ts)


def read_offset(path, tz):
    text = read_text(path)
    rd = csv.DictReader(io.StringIO(text), delimiter=';', quotechar='"')
    for r in rd:
        if not r.get('punch_id'):
            continue
        dt = datetime.fromisoformat(r['timestamp'].strip())
        ev = r['event'].strip().lower()
        yield (r['punch_id'], r['employee'], 'IN' if ev == 'clock_in' else 'OUT', to_epoch(dt))


def read_legacy(path, tz):
    off = None
    for line in lines_of(path):
        t = line[0]
        if t == 'H':
            o = line[13:18].strip()
            if o and o[0] in '+-' and len(o) == 5:
                sec = (int(o[1:3]) * 60 + int(o[3:5])) * 60
                off = timedelta(seconds=sec if o[0] == '+' else -sec)
            else:
                off = None
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            d = line[15]
            dt = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
            o = off if off is not None else std_offset(tz, dt)
            ep = to_epoch(dt.replace(tzinfo=UTC) - o)
            yield (pid, 'E' + badge, 'IN' if d == 'I' else 'OUT', ep)


def read_de(path, tz):
    lines = lines_of(path)
    header = None
    for line in lines:
        row = [c.strip() for c in line.split('\t')]
        if 'Ausweis' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d, mo, y = r['Datum'].split('.')
        hh, mm = r['Uhrzeit'].split(':')[:2]
        naive = datetime(int(y), int(mo), int(d), int(hh), int(mm))
        fold = 0 if r['Zeitzone'].upper() == 'MESZ' else 1
        yield (r['Nr'], r['Ausweis'], 'IN' if r['Buchung'].upper() == 'K' else 'OUT',
               local_to_epoch(naive, tz, fold))


def read_localcsv(path, tz):
