            continue
        naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        yield (r['punch_ref'].strip(), r['employee_id'].strip(), r['direction'].strip().upper(),
               local_to_epoch(naive, tz, 0))


def read_localjsonl(path, tz):
