        o = json.loads(line)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        yield (str(p['id']), p['badge'], str(p['type']).upper(), local_to_epoch(naive, tz, 0))


