    period = json.load(open(os.path.join(indir, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))

    sites = {}
    with open(os.path.join(indir, 'sites.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    with open(os.path.join(indir, 'employees.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(indir, 'rates.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

