    punches = {}  # (site, id) -> [emp, dir, epoch]
    ever = set()
    for site, (tz, fmt) in sites.items():
        for path in files_in(os.path.join(indir, 'exports', site)):
            for pid, emp, d, ep in READERS[fmt](path, tz):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp.strip(), d, ep]

    # 2. corrections
    corr = []
    for path in files_in(os.path.join(indir, 'corrections')):
