        for r in rd:
            if not r.get('correction_id'):
                continue
            ia = datetime.fromisoformat(r['issued_at'].strip().replace('Z', '+00:00'))
            corr.append((ia, r['correction_id'], r))
    corr.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for ia, cid, r in corr:
        if ia > cutoff:
            continue
        k = (r['site'].strip(), r['punch_id'].strip())
        act = r['action'].strip().lower()
