                ever.add(k)
                punches[k] = [r['employee'].strip(), r['type'].strip().upper(),
                              to_epoch(datetime.fromisoformat(r['time'].strip().replace('Z', '+00:00')))]
                applied += 1

    byemp = {}
    for (site, pid), (emp, d, ep) in punches.items():
        if emp in employees:
            byemp.setdefault(emp, []).append((ep, 0 if d == 'OUT' else 1, site, pid, d))

    def rnd(ep, tz):
        off = int(datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
        return ((ep + off + 180) // 360) * 360 - off

    emp_out = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
