            kept.append((r, site, d))

        shifts = []  # (in_r, out_r, site, workday)
        i = 0
        n = len(kept)
        while i < n:
            r, site, d = kept[i]
            if d == 'IN':
                if i + 1 < n and kept[i + 1][2] == 'OUT' and kept[i + 1][0] - r <= 16 * 3600:
                    shifts.append((r, kept[i + 1][0], site, workday(r)))
                    i += 2
                    continue
                if pstart <= workday(r) <= pend:
                    exc['open_shifts'] += 1
            else:
                if pstart <= workday(r) <= pend:
                    exc['orphan_outs'] += 1
            i += 1

        shifts = [s for s in shifts if pstart <= s[3] <= pend]
        shifts.sort(key=lambda s: s[0])
        daily = {}
        weekly = {}
        o = emp_out[emp]
        rl = rates.get(emp, [])
        for rin, rout, site, wd in shifts:
            tz = sites[site][0]
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night
            night = 0
            d0 = datetime.fromtimestamp(rin, UTC).astimezone(tz).date() - timedelta(days=1)
            d1 = datetime.fromtimestamp(rout, UTC).astimezone(tz).date()
            dd = d0
            while dd <= d1:
                a = local_to_epoch(datetime.combine(dd, dtime(22, 0)), tz)
                b = local_to_epoch(datetime.combine(dd + timedelta(days=1), dtime(6, 0)), tz)
                lo, hi = max(a, rin), min(b, rout)
                if hi > lo:
                    night += (hi - lo) / 60
                dd += timedelta(days=1)
            night = min(int(night), paid)
            # overtime
            before = daily.get(wd, 0)
            dot = max(0, before + paid - 480) - max(0, before - 480)
            daily[wd] = before + paid
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = weekly.get(wk, 0)
            wot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            weekly[wk] = wb + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rt in rl:
                if eff <= wd:
                    rate = rt
            if rate is None and rl:
                rate = rl[0][1]
            rate = Fraction(rate or 0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            o['shifts'] += 1
            o['paid_minutes'] += paid
            o['overtime_minutes'] += ot
            o['night_minutes'] += night
            o['gross'] += pay

    def cents(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return c

    res_emp = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e in sorted(employees):
        o = emp_out[e]
        c = cents(o['gross'])
        totc += c
        for k in tot:
            tot[k] += o[k]
        res_emp[e] = {k: o[k] for k in tot}
        res_emp[e]['gross'] = '%d.%02d' % divmod(c, 100)
    tot['gross'] = '%d.%02d' % divmod(totc, 100)
    out = dict(period=dict(start=period['start'], end=period['end']), employees=res_emp,
               exceptions=exc, totals=tot)
    with open(outfile, 'w') as f:
        json.dump(out, f, indent=1)


